import { Link, createFileRoute, redirect, useRouter } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useState } from "react";
import { VendorShell } from "~/components/vendor-chrome";
import { CITIES } from "~/lib/taxonomy";
import { fetchVendorMe } from "~/server/vendor-functions";
import { fetchVendorClaimStatus, searchClaimBusinesses, submitListingClaim, type ClaimSearchBusiness } from "~/server/listing-claim-functions";

export const Route = createFileRoute("/vendor/claim")({
  head: () => ({ meta: [{ title: "Claim your directory listing | Shop My Neighborhood" }] }),
  loader: async () => { const me = await fetchVendorMe(); if (!me) throw redirect({ to: "/vendor/login" }); const claim = await fetchVendorClaimStatus(); return { me, claim: claim === "unauthenticated" ? null : claim }; },
  component: ClaimPage,
});
function ClaimPage() {
  const { me, claim } = Route.useLoaderData(); const router = useRouter();
  const search = useServerFn(searchClaimBusinesses); const submit = useServerFn(submitListingClaim);
  const [q, setQ] = useState(""); const [city, setCity] = useState(me.citySlug); const [rows, setRows] = useState<ClaimSearchBusiness[]>([]);
  const [selected, setSelected] = useState<ClaimSearchBusiness | null>(null); const [note, setNote] = useState(""); const [notice, setNotice] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  async function runSearch(e: React.FormEvent) { e.preventDefault(); setBusy(true); setNotice(null); try { const found = await search({ data: { q, city } }); if (found === "unauthenticated") return; setRows(found); setSelected(null); } finally { setBusy(false); } }
  async function onSubmit(e: React.FormEvent) { e.preventDefault(); if (!selected) return; setBusy(true); setNotice(null); try { const result = await submit({ data: { businessId: selected.id, proofNote: note } }); setNotice(result.message); if (result.ok) await router.invalidate(); } catch { setNotice("That claim could not be submitted. Please try again."); } finally { setBusy(false); } }
  return <VendorShell vendorName={me.businessName} tierLabel={me.tierLabel}><div className="mx-auto max-w-4xl px-4 py-7"><p className="kicker">Free directory listing</p><h1 className="mt-1 font-display text-3xl font-semibold text-brand-dark">Claim your business listing</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-ink-soft">Search the Lake County directory, select your business and send a short ownership note. If your account email domain matches the listing website, we approve it automatically; otherwise we review it and contact you at your account email.</p>{claim ? <section className="mt-6 rounded-2xl border border-brand/20 bg-white p-5 shadow-sm"><p className="text-xs font-bold uppercase tracking-[0.13em] text-ink-soft">Current claim</p><h2 className="mt-1 font-display text-xl font-semibold text-brand-dark">{claim.business_name}</h2><p className="mt-2 text-sm text-ink-soft"><span className="font-semibold capitalize text-ink">{claim.status}</span> · submitted {new Date(claim.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}{claim.decided_note ? ` · ${claim.decided_note}` : ""}</p>{claim.status === "approved" && <Link to="/vendor/listing" className="mt-4 inline-block rounded-full bg-brand px-4 py-2 text-sm font-semibold text-white hover:bg-brand-dark">Edit your listing</Link>}</section> : <><form onSubmit={runSearch} className="mt-6 grid gap-3 rounded-2xl border border-black/5 bg-white p-5 shadow-sm sm:grid-cols-[1fr_220px_auto]"><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Business name (optional)" className="rounded-xl border border-black/10 px-3 py-2.5 text-sm" /><select value={city} onChange={(e) => setCity(e.target.value)} className="rounded-xl border border-black/10 px-3 py-2.5 text-sm"><option value="">All cities</option>{CITIES.map((c) => <option key={c.slug} value={c.slug}>{c.name}</option>)}</select><button disabled={busy || (!q.trim() && !city)} className="rounded-xl bg-brand px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{busy ? "Searching…" : "Search"}</button></form>{rows.length > 0 && <form onSubmit={onSubmit} className="mt-5 rounded-2xl border border-black/5 bg-white p-5 shadow-sm"><h2 className="font-display text-xl font-semibold text-brand-dark">Choose your business</h2><div className="mt-3 max-h-80 space-y-2 overflow-y-auto">{rows.map((business) => <label key={business.id} className={`block cursor-pointer rounded-xl border p-3 text-sm ${selected?.id === business.id ? "border-brand bg-brand/5" : "border-black/10"}`}><input type="radio" name="business" className="mr-2" checked={selected?.id === business.id} onChange={() => setSelected(business)} /> <span className="font-semibold text-ink">{business.name}</span><span className="ml-2 text-ink-soft">{business.city_name}</span>{business.website && <span className="ml-2 text-xs text-ink-soft">{business.website}</span>}</label>)}</div><label className="mt-4 block text-sm font-semibold text-ink">Ownership note <span className="font-normal text-ink-soft">(optional)</span><textarea value={note} onChange={(e) => setNote(e.target.value)} maxLength={500} placeholder="I'm the owner / manager…" className="mt-1.5 min-h-24 w-full rounded-xl border border-black/10 p-3 text-sm font-normal" /></label><button disabled={!selected || busy} className="mt-4 rounded-full bg-brand-green px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{busy ? "Submitting…" : "Submit claim"}</button></form>}{rows.length === 0 && (q || city) && <p className="mt-4 text-sm text-ink-soft">Search by name or city to find your unclaimed listing.</p>}</>}{notice && <p className="mt-4 rounded-xl bg-brand/10 px-4 py-3 text-sm text-brand-dark">{notice}</p>}</div></VendorShell>;
}
